// Payroll preview uses actual closed attendance. Breaks are paid in full.
db.payrollDrafts??={};db.payrollRuns??=[];db.hourlyProfiles??={};
const payrollRender=render;navs.find(n=>n[0]==='payroll')[2]='المرتبات والتقفيل';
const payrollTypes={captain:'كابتن',sales:'سيلز',housekeeping:'هاوس كيبنج',hr:'HR',quality:'كواليتي',assessment:'أسسمنت — دكتور علاج طبيعي'};
let payrollPeriod={from:cairoDay().slice(0,7)+'-01',to:cairoDay()};let payrollEmployee=null;
function currency(cents){return (cents/100).toLocaleString('ar-EG',{minimumFractionDigits:2,maximumFractionDigits:2})+' ج.م'}
function moneyCents(value){let s=String(value??'').trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace('٫','.');if(!s)s='0';if(!/^\d+(?:\.\d{1,2})?$/.test(s))throw Error('اكتب مبلغ موجب بحد أقصى رقمين بعد العلامة العشرية');const [whole,frac='']=s.split('.'),n=Number(whole)*100+Number(frac.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n>100000000000)throw Error('المبلغ أكبر من الحد المسموح');return n}
function decimal(cents){return (cents/100).toFixed(2)}
function periodBounds(period){if(!/^\d{4}-\d\d-\d\d$/.test(period.from)||!/^\d{4}-\d\d-\d\d$/.test(period.to)||period.from>period.to)throw Error('اختار فترة صحيحة من وإلى');const next=new Date(period.to+'T12:00:00Z');if(!Number.isFinite(next.getTime()))throw Error('تاريخ غير صحيح');next.setUTCDate(next.getUTCDate()+1);return {start:Date.parse(cairoToISO(period.from+'T00:00')),end:Date.parse(cairoToISO(next.toISOString().slice(0,10)+'T00:00'))}}
function attendanceHours(employeeId,period){const {start,end}=periodBounds(period);const matches=db.punches.filter(p=>p.employeeId===employeeId&&Date.parse(p.in)<end&&(!p.out||Date.parse(p.out)>start));const closed=[],open=[];let milliseconds=0;for(const p of matches){if(!p.out){open.push(p);continue}const a=Math.max(start,Date.parse(p.in)),b=Math.min(end,Date.parse(p.out));if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a)continue;milliseconds+=b-a;closed.push({id:p.id,in:p.in,out:p.out,branch:p.branch,name:p.name,source:p.source==='manual'?'إداري':'GPS',milliseconds:b-a,fullMilliseconds:Date.parse(p.out)-Date.parse(p.in),revisions:p.revisions?.length||0})}const ordered=closed.map(p=>[Math.max(start,Date.parse(p.in)),Math.min(end,Date.parse(p.out))]).sort((a,b)=>a[0]-b[0]);let overlap=false;for(let i=1;i<ordered.length;i++)if(ordered[i][0]<ordered[i-1][1])overlap=true;const opening=(db.attendanceOpening||[]).filter(o=>Number(o.employeeId)===Number(employeeId)&&o.date>=period.from&&o.date<=period.to),openingHours=opening.reduce((x,o)=>x+Number(o.hours||0),0),openingShifts=opening.reduce((x,o)=>x+Number(o.shifts||0),0);milliseconds+=openingHours*36e5;return {milliseconds,hours:milliseconds/36e5,closed,open,overlap,opening,openingHours,openingShifts,fingerprint:JSON.stringify({opening:opening.map(o=>[o.id,o.date,o.shifts,o.hoursPerShift,o.updatedAt||o.createdAt]),closed:closed.map(p=>[p.id,p.in,p.out,p.branch,p.revisions]).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))),open:open.map(p=>[p.id,p.in])})}}
function payrollKey(id,period=payrollPeriod){return id+':'+period.from+':'+period.to}
const PAYROLL_LINE_LABELS=['بدل إشراف','دخل العيادة','اشتراكات خاصة إضافية','جزاء إداري','إدراكات عمل','إضافة أخرى','خصم آخر'];
function defaultPayroll(id){const p=db.hourlyProfiles[id]||{};return {type:p.type||'',hourlyRate:p.hourlyRate??'',privateTotal:'0',privateDraw:'0',employeeDraw:'0',bonus:'0',incentive:'0',targetBonus:'0',targetAchieved:false,notes:'',lines:[]}}
function payrollDraft(id,period=payrollPeriod){return db.payrollDrafts[payrollKey(id,period)]||defaultPayroll(id)}
function payrollCompute(draft,attendance){if(!payrollTypes[draft.type])throw Error('حدد نوع الموظف من القائمة');const rate=moneyCents(draft.hourlyRate);const base=Number((BigInt(attendance.milliseconds)*BigInt(rate)+1800000n)/3600000n);if(!Number.isSafeInteger(base))throw Error('قيمة أجر الساعات أكبر من الحد المسموح');const bonus=moneyCents(draft.bonus),draw=moneyCents(draft.employeeDraw);const incentive=draft.type!=='housekeeping'?moneyCents(draft.incentive):0;const privateTotal=draft.type==='captain'?moneyCents(draft.privateTotal):0,privateShare=draft.type==='captain'?Math.round(privateTotal/2):0,privateDraw=draft.type==='captain'?moneyCents(draft.privateDraw):0;const targetBonus=draft.type==='sales'&&draft.targetAchieved?moneyCents(draft.targetBonus):0;const lines=(draft.lines||[]).map((l,i)=>{const label=String(l.label||'').trim(),reason=String(l.reason||'').trim();if(!PAYROLL_LINE_LABELS.includes(label))throw Error('اختار نوع البند اليدوي من القائمة (سطر '+(i+1)+')');if(!reason)throw Error('سبب البند «'+label+'» إجباري (سطر '+(i+1)+')');const amount=moneyCents(l.amount);if(amount<=0)throw Error('مبلغ البند «'+label+'» لازم يكون أكبر من صفر (سطر '+(i+1)+')');return {label,sign:l.sign==='-'?'-':'+',amount,reason}});const linesAdd=lines.filter(l=>l.sign==='+').reduce((s,l)=>s+l.amount,0),linesSub=lines.filter(l=>l.sign==='-').reduce((s,l)=>s+l.amount,0);const earnings=base+privateShare+bonus+incentive+targetBonus+linesAdd,withdrawals=draw+privateDraw+linesSub;return {rate,base,privateTotal,privateShare,privateDraw,draw,bonus,incentive,targetBonus,lines,linesAdd,linesSub,earnings,withdrawals,total:earnings-withdrawals,hours:attendance.hours}}
function closedPayroll(id,period=payrollPeriod){return db.payrollRuns.find(r=>r.employeeId===id&&r.status==='closed'&&r.period.from===period.from&&r.period.to===period.to)}
function payrollAvailableEmployees(){const branch=$('#branch').value;return allEmployees().filter(s=>(branch==='كل الفروع'||s.branch===branch)&&(!db.archived.some(a=>a.id===s.id)||db.punches.some(p=>p.employeeId===s.id)||(db.attendanceOpening||[]).some(o=>Number(o.employeeId)===Number(s.id))))}
function payrollAmountField(title,name,value){return `<label>${title}<input type="text" inputmode="decimal" name="${name}" value="${esc(value??'0')}" autocomplete="off"></label>`}
function savedSnapshot(id,period=payrollPeriod){const employee=allEmployees().find(s=>s.id===id);if(!employee)throw Error('الموظف غير موجود');const draft=structuredClone(payrollDraft(id,period)),attendance=attendanceHours(id,period),calculation=payrollCompute(draft,attendance);return {employeeId:id,employeeName:employee.name,branch:employee.branch,period:structuredClone(period),draft,attendance,calculation}}
function closePayroll(id,period=payrollPeriod){if(closedPayroll(id,period))throw Error('الفترة مقفولة بالفعل');if(period.to>cairoDay())throw Error('لا يمكن تقفيل فترة مستقبلية');const clash=db.payrollRuns.find(r=>r.employeeId===id&&r.status==='closed'&&r.period.from<=period.to&&r.period.to>=period.from);if(clash)throw Error('فيه تقفيل قائم ومتداخل مع الفترة دي؛ راجعه قبل إنشاء تقفيل جديد');const snapshot=savedSnapshot(id,period);if(snapshot.attendance.open.length)throw Error('أنهِ أو صحح الورديات المفتوحة قبل التقفيل');if(snapshot.attendance.overlap)throw Error('في سجلات حضور متداخلة؛ صححها قبل التقفيل');if(!snapshot.attendance.closed.length&&!snapshot.attendance.opening?.length)throw Error('لا توجد ساعات حضور مغلقة أو رصيد افتتاحي في الفترة');if(snapshot.calculation.rate<=0)throw Error('سعر الساعة لازم يكون أكبر من صفر للتقفيل');const run={id:crypto.randomUUID(),...snapshot,closedAt:new Date().toISOString(),status:'closed',history:[]};db.payrollRuns.push(run);audit('تقفيل محلي: '+run.employeeName+' من '+period.from+' إلى '+period.to);return run}
function reopenPayroll(run,reason){if(run.status!=='closed')throw Error('التقفيل مفتوح بالفعل');if(!reason?.trim())throw Error('سبب إعادة الفتح مطلوب');run.status='reopened';run.history.push({at:new Date().toISOString(),action:'reopened',reason:reason.trim()});db.payrollDrafts[payrollKey(run.employeeId,run.period)]=structuredClone(run.draft);audit('إعادة فتح تقفيل '+run.employeeName+' — '+reason.trim())}
function payrollLineItems(s){const c=s.calculation,d=s.draft;return [['ساعات الحضور المدفوعة (شاملة البريك)',s.attendance.hours.toFixed(4)+' ساعة'],...(s.attendance.openingHours?[['منها رصيد افتتاحي قبل التطبيق ('+s.attendance.openingShifts+' شيفت)',Number(s.attendance.openingHours).toFixed(4)+' ساعة']]:[]),['سعر الساعة',currency(c.rate)],['أجر الحضور = الساعات × السعر',currency(c.base)],...(d.type==='captain'?[['إجمالي البرايفيت المدخل',currency(c.privateTotal)],['نصيب الكابتن من البرايفيت ٥٠٪',currency(c.privateShare)],['مسحوبات البرايفيت',currency(c.privateDraw)]]:[]),['البونص',currency(c.bonus)],...(d.type!=='housekeeping'?[['الحافز',currency(c.incentive)]]:[]),...(d.type==='sales'?[['التارجيت',d.targetAchieved?'متحقق':'غير متحقق'],['مكافأة التارجيت المستحقة',currency(c.targetBonus)]]:[]),[d.type==='captain'?'مسحوبات الكابتن':'المسحوبات',currency(c.draw)],...(c.lines||[]).map(l=>[(l.sign==='+'?'إضافة':'خصم')+' — '+l.label+' ('+l.reason+')',(l.sign==='+'?'+':'−')+' '+currency(l.amount)]),['إجمالي المستحقات قبل المسحوبات',currency(c.earnings)],['إجمالي المسحوبات',currency(c.withdrawals)],['الصافي المستحق',currency(c.total)]]}
function payslipHTML(s,closed=false){const c=s.calculation;return `<div class="payslip-paper" id="payrollPaper"><div class="report-brand"><div><b>ENERGY <span>STAFF</span></b><p>كشف تقفيل مرتب ${closed?'— مقفول محليًا':'— مسودة'}</p></div><div>${esc(s.period.from)} إلى ${esc(s.period.to)}<br><small>${closed?'تاريخ التقفيل: '+stamp(s.closedAt):'تاريخ المعاينة: '+stamp(new Date().toISOString())}</small></div></div><div class="payslip-person"><h2>${esc(s.employeeName)}</h2><p>${esc(payrollTypes[s.draft.type])} • ${esc(s.branch)}</p></div><div class="payslip-total ${c.total<0?'negative-total':''}"><span>${c.total<0?'رصيد سالب — المسحوبات أكبر من المستحق':'صافي المستحق'}</span><strong>${currency(c.total)}</strong><small>${s.attendance.hours.toFixed(4)} ساعة حضور • البريك مدفوع بالكامل</small></div><table><tbody>${payrollLineItems(s).map(([t,v])=>`<tr><td>${esc(t)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table>${s.draft.notes?`<p class="payroll-notes">ملاحظات: ${esc(s.draft.notes)}</p>`:''}<h3>تفاصيل ساعات الحضور</h3><div class="table-wrap"><table><tr><th>الحضور بالقاهرة</th><th>الانصراف بالقاهرة</th><th>الساعات داخل الفترة</th><th>المصدر</th></tr>${s.attendance.closed.map(p=>`<tr><td>${stamp(p.in)}</td><td>${stamp(p.out)}</td><td>${(p.milliseconds/36e5).toFixed(4)}</td><td>${p.source}</td></tr>`).join('')}${(s.attendance.opening||[]).map(o=>`<tr><td>${esc(o.date)}</td><td>—</td><td>${Number(o.hours).toFixed(4)}</td><td>رصيد افتتاحي إداري — ${o.shifts} شيفت × ${o.hoursPerShift} ساعة${o.reason?' — '+esc(o.reason):''}</td></tr>`).join('')}</table></div><div class="report-signatures"><span>الموظف<br>________________</span><span>إعداد الحسابات<br>________________</span><span>اعتماد الإدارة<br>________________</span></div><p class="report-disclaimer">جميع المبالغ بالجنيه المصري • تقريب المبالغ لأقرب قرش بعد حساب المكون بالكامل • ساعات البريك لا تخصم • تجاوزات البريك والنقاط منفصلة، ولا يوجد خصم منها هنا • ${closed?'نسخة محفوظة وقت التقفيل':'مسودة قابلة للتغيير'} • ليس إثباتًا لصرف نقدي • بيانات هذه النسخة محفوظة محليًا.</p></div>`}
function payrollPreview(id){const closed=closedPayroll(id);let snapshot;try{snapshot=closed||savedSnapshot(id)}catch(e){return `<div class="empty">${esc(e.message)} — احفظ نوع الموظف وسعر الساعة لعرض الكشف.</div>`}const changed=closed&&closed.attendance.fingerprint!==attendanceHours(id,payrollPeriod).fingerprint;return `${changed?'<div class="notice">سجل الحضور اتغير بعد التقفيل. الكشف المقفول يحتفظ بأرقامه؛ أعد فتحه بسبب واضح لو محتاج تحديثه.</div>':''}${snapshot.attendance.open.length?'<div class="notice">فيه ورديات مفتوحة مستبعدة من المبلغ؛ لازم تتقفل قبل التقفيل.</div>':''}${snapshot.attendance.overlap?'<div class="notice">في سجلات متداخلة؛ راجعها قبل التقفيل.</div>':''}${payslipHTML(snapshot,!!closed)}<div class="toolbar no-print"><button id="slipCSV">↓ تصدير كشف الموظف CSV</button><button id="slipPrint">طباعة / حفظ PDF للموظف</button>${closed?'<button id="reopenPayroll">إعادة فتح بسبب</button>':'<button id="closePayroll" class="primary">تقفيل وحفظ نسخة</button>'}</div>`}
function payrollLineRowHTML(l={}){return '<div class="payroll-line-row"><select data-line-label>'+PAYROLL_LINE_LABELS.map(x=>'<option '+(l.label===x?'selected':'')+'>'+x+'</option>').join('')+'</select><select data-line-sign><option value="+" '+(l.sign!=='-'?'selected':'')+'>إضافة ＋</option><option value="-" '+(l.sign==='-'?'selected':'')+'>خصم −</option></select><input data-line-amount type="number" min="0" step="0.01" inputmode="decimal" placeholder="المبلغ بالجنيه" value="'+esc(l.amount??'')+'"><input data-line-reason maxlength="200" placeholder="السبب (إجباري)" value="'+esc(l.reason||'')+'"><button type="button" data-line-remove title="حذف البند">✕</button></div>'}
function collectPayrollLines(form){return [...form.querySelectorAll('.payroll-line-row')].map(r=>({label:r.querySelector('[data-line-label]').value,sign:r.querySelector('[data-line-sign]').value,amount:r.querySelector('[data-line-amount]').value,reason:r.querySelector('[data-line-reason]').value})).filter(l=>l.amount!==''||l.reason!=='')}
function payrollView(){const employees=payrollAvailableEmployees();if(!employees.some(s=>s.id===payrollEmployee))payrollEmployee=employees[0]?.id;const s=employees.find(s=>s.id===payrollEmployee),d=s?payrollDraft(s.id):null,closed=s?closedPayroll(s.id):null;return `<div class="notice no-print">تقفيل على ساعات الحضور الفعلية كاملة، والبريك إضافي لا يخصم من الأجر. التقفيل يحفظ نسخة ثابتة، ولا يسجل صرفًا ماليًا. هذه نسخة محلية تجريبية.</div>${card('فترة المرتبات',`<form class="toolbar payroll-period" id="payrollPeriod"><label>من<input required type="date" name="from" value="${payrollPeriod.from}"></label><label>إلى<input required type="date" name="to" value="${payrollPeriod.to}"></label><button class="primary">عرض الساعات والتقفيل</button><button type="button" id="payrollAllCSV">↓ ملخص كل الموظفين</button></form>`)}${card('ساعات كل موظف ومستحقاته',`<div class="table-wrap"><table><tr><th>الموظف</th><th>ساعات الحضور</th><th>ورديات مفتوحة</th><th>نوع التقفيل</th><th>الصافي</th><th>الحالة</th><th>كشف الموظف</th></tr>${employees.map(e=>{const a=attendanceHours(e.id,payrollPeriod),r=closedPayroll(e.id),draft=payrollDraft(e.id);let total='غير مكتمل';try{total=currency((r?.calculation||payrollCompute(draft,a)).total)}catch{}return `<tr><td>${esc(e.name)}</td><td>${(r?.attendance.hours??a.hours).toFixed(4)}</td><td>${a.open.length}</td><td>${esc(payrollTypes[(r?.draft||draft).type]||'حدد النوع')}</td><td>${total}</td><td>${r?'مقفول محليًا':'مسودة'}</td><td><button data-payroll-employee="${e.id}">${e.id===payrollEmployee?'محدد ✓':'فتح الكشف'}</button></td></tr>`}).join('')}</table></div>`)}${s?`<div class="payroll-layout"><section class="card payroll-editor no-print"><div class="card-head"><h2>بيانات تقفيل ${esc(s.name)}</h2></div><form id="payrollEmployeeForm" class="payroll-fields"><fieldset ${closed?'disabled':''}><label>نوع الموظف<select name="type" required><option value="">اختار النوع</option>${Object.entries(payrollTypes).map(([k,t])=>`<option value="${k}" ${d.type===k?'selected':''}>${t}</option>`).join('')}</select></label>${payrollAmountField('سعر الساعة بالجنيه','hourlyRate',d.hourlyRate)}<div class="captain-fields" ${d.type!=='captain'?'hidden':''}>${payrollAmountField('إجمالي البرايفيت — نصيب الكابتن ٥٠٪ تلقائيًا','privateTotal',d.privateTotal)}${payrollAmountField('مسحوبات من البرايفيت','privateDraw',d.privateDraw)}</div>${payrollAmountField(d.type==='captain'?'مسحوبات الكابتن':'المسحوبات','employeeDraw',d.employeeDraw)}${payrollAmountField('البونص','bonus',d.bonus)}<div class="incentive-fields" ${d.type==='housekeeping'||!d.type?'hidden':''}>${payrollAmountField('الحافز','incentive',d.incentive)}</div><div class="sales-fields" ${d.type!=='sales'?'hidden':''}><label class="permission-item"><input type="checkbox" name="targetAchieved" ${d.targetAchieved?'checked':''}>التارجيت اتحقق</label>${payrollAmountField('مكافأة تحقيق التارجيت','targetBonus',d.targetBonus)}<small>المبلغ يدخل الصافي فقط عند تفعيل «التارجيت اتحقق».</small></div><fieldset class="payroll-lines-box"><legend>بنود يدوية على التقفيلة (بدل إشراف / جزاء إداري / إدراكات عمل…)</legend><div id="payrollLines">${(d.lines||[]).map(l=>payrollLineRowHTML(l)).join('')}</div><button type="button" id="addPayrollLine">＋ إضافة بند</button><small>كل بند لازم يتسجل بسببه — بيظهر في كشف المرتب وملف الـ CSV. مفيش خصم تلقائي من النقاط أو التنبيهات.</small></fieldset><label>ملاحظات<textarea name="notes" rows="3" maxlength="1000">${esc(d.notes||'')}</textarea></label><button class="primary" type="submit">حفظ المسودة وحساب الصافي</button></fieldset>${closed?'<p>البيانات مقفولة؛ أعد فتح التقفيل للتعديل.</p>':''}<p id="payrollDirty" class="payroll-dirty" hidden>في تعديلات غير محفوظة. احفظها لتحديث الكشف.</p></form></section><div id="payrollPreview">${payrollPreview(s.id)}</div></div>`:'<p class="empty">لا يوجد موظفون في الفرع المحدد</p>'}${card('سجل التقفيلات',`<div class="table-wrap"><table><tr><th>الموظف</th><th>الفترة</th><th>الساعات المحفوظة</th><th>الصافي</th><th>الحالة</th><th>التصدير</th></tr>${db.payrollRuns.filter(r=>employees.some(e=>e.id===r.employeeId)).slice().reverse().map(r=>`<tr><td>${esc(r.employeeName)}</td><td>${r.period.from} — ${r.period.to}</td><td>${r.attendance.hours.toFixed(4)}</td><td>${currency(r.calculation.total)}</td><td>${r.status==='closed'?'مقفول محليًا':'أعيد فتحه'}${r.history.length?'<br>'+esc(r.history.at(-1).reason):''}</td><td><button data-run-export="${r.id}">CSV محفوظ</button></td></tr>`).join('')}</table></div>`)}`}
function payrollCSVRows(s){return [['كشف مرتب',s.employeeName],['النوع',payrollTypes[s.draft.type]],['الفرع',s.branch],['من',s.period.from],['إلى',s.period.to],['الحالة',s.status==='closed'?'مقفول محليًا':'مسودة / أعيد فتحه'],['سعر الساعة بالجنيه',decimal(s.calculation.rate)],['ساعات الحضور شاملة البريك',s.attendance.hours.toFixed(8)],...(s.attendance.openingHours?[['منها رصيد افتتاحي قبل التطبيق (ساعات)',Number(s.attendance.openingHours).toFixed(8)],['شيفتات الرصيد الافتتاحي',String(s.attendance.openingShifts)]]:[]),['أجر الحضور بالجنيه',decimal(s.calculation.base)],...(s.draft.type==='captain'?[['إجمالي البرايفيت',decimal(s.calculation.privateTotal)],['نصيب الكابتن 50%',decimal(s.calculation.privateShare)],['مسحوبات البرايفيت',decimal(s.calculation.privateDraw)]]:[]),['البونص',decimal(s.calculation.bonus)],...(s.draft.type!=='housekeeping'?[['الحافز',decimal(s.calculation.incentive)]]:[]),...(s.draft.type==='sales'?[['التارجيت متحقق',s.draft.targetAchieved?'نعم':'لا'],['مكافأة التارجيت المحتسبة',decimal(s.calculation.targetBonus)]]:[]),['المسحوبات',decimal(s.calculation.draw)],...(s.calculation.lines||[]).map(l=>[(l.sign==='+'?'إضافة':'خصم')+' — '+l.label+' — '+l.reason,(l.sign==='-'?'-':'')+decimal(l.amount)]),['إجمالي المستحقات',decimal(s.calculation.earnings)],['إجمالي المسحوبات',decimal(s.calculation.withdrawals)],['الصافي',decimal(s.calculation.total)],['ملاحظات',s.draft.notes||''],[],['الحضور بالقاهرة','الانصراف بالقاهرة','الساعات داخل الفترة','المصدر'],...s.attendance.closed.map(p=>[stamp(p.in),stamp(p.out),(p.milliseconds/36e5).toFixed(8),p.source]),...(s.attendance.opening||[]).map(o=>[o.date,'—',Number(o.hours).toFixed(8),'رصيد افتتاحي إداري — '+(o.reason||'')]),[],['البريك مدفوع بالكامل. كشف محلي وليس إثبات صرف.']]}
function downloadPayrollCSV(rows,name){const quote=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s)&&!/^[-]?\d+(?:\.\d+)?$/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportPaySummary(){const rows=[['الموظف','من','إلى','النوع','الساعات المدفوعة','سعر الساعة','أجر الحضور','نصيب البرايفيت','البونص','الحافز','مكافأة التارجيت','مسحوبات البرايفيت','المسحوبات','صافي البنود اليدوية','الصافي','الحالة']];for(const s of payrollAvailableEmployees()){try{const r=closedPayroll(s.id)||savedSnapshot(s.id);const c=r.calculation;rows.push([s.name,r.period.from,r.period.to,payrollTypes[r.draft.type],r.attendance.hours.toFixed(8),decimal(c.rate),decimal(c.base),decimal(c.privateShare),decimal(c.bonus),decimal(c.incentive),decimal(c.targetBonus),decimal(c.privateDraw),decimal(c.draw),decimal((c.linesAdd||0)-(c.linesSub||0)),decimal(c.total),r.status==='closed'?'مقفول محليًا':'مسودة'])}catch{rows.push([s.name,payrollPeriod.from,payrollPeriod.to,'غير مكتمل',attendanceHours(s.id,payrollPeriod).hours.toFixed(8),'','','','','','','','','','','لم يحدد النوع / المبالغ'])}}downloadPayrollCSV(rows,'Energy-Payroll-Summary-'+payrollPeriod.from+'.csv')}
function bindPayroll(){const s=allEmployees().find(s=>s.id===payrollEmployee);$('#payrollPeriod').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p={from:f.get('from'),to:f.get('to')};try{periodBounds(p);payrollPeriod=p;render()}catch(err){toast(err.message)}};$('#payrollAllCSV').onclick=exportPaySummary;document.querySelectorAll('[data-payroll-employee]').forEach(b=>b.onclick=()=>{payrollEmployee=Number(b.dataset.payrollEmployee);render()});document.querySelectorAll('[data-run-export]').forEach(b=>b.onclick=()=>{const r=db.payrollRuns.find(r=>r.id===b.dataset.runExport);downloadPayrollCSV(payrollCSVRows(r),'Energy-Payslip-'+r.employeeId+'-'+r.period.from+'.csv')});if(!s)return;const form=$('#payrollEmployeeForm');form.oninput=()=>{$('#payrollDirty').hidden=false;document.querySelectorAll('#closePayroll,#slipCSV,#slipPrint').forEach(b=>b.disabled=true)};form.querySelector('[name="type"]').onchange=e=>{form.querySelector('.captain-fields').hidden=e.target.value!=='captain';form.querySelector('.sales-fields').hidden=e.target.value!=='sales';form.querySelector('.incentive-fields').hidden=!e.target.value||e.target.value==='housekeeping'};$('#addPayrollLine').onclick=()=>{$('#payrollLines').insertAdjacentHTML('beforeend',payrollLineRowHTML());form.dispatchEvent(new Event('input',{bubbles:true}))};form.addEventListener('click',e=>{const b=e.target.closest('[data-line-remove]');if(b){b.closest('.payroll-line-row').remove();form.dispatchEvent(new Event('input',{bubbles:true}))}});form.onsubmit=e=>{e.preventDefault();if(closedPayroll(s.id))return toast('التقفيل مقفول');try{const f=new FormData(form),d={...Object.fromEntries(f),targetAchieved:f.has('targetAchieved'),lines:collectPayrollLines(form)};const a=attendanceHours(s.id,payrollPeriod);payrollCompute(d,a);db.payrollDrafts[payrollKey(s.id)]=d;db.hourlyProfiles[s.id]={type:d.type,hourlyRate:d.hourlyRate};audit('حفظ مسودة مرتب '+s.name);render();toast('تم حساب وحفظ مسودة الموظف')}catch(err){toast(err.message)}};$('#slipCSV')?.addEventListener('click',()=>{try{const r=closedPayroll(s.id)||savedSnapshot(s.id);downloadPayrollCSV(payrollCSVRows(r),'Energy-Payslip-'+s.id+'-'+payrollPeriod.from+'.csv')}catch(e){toast(e.message)}});$('#slipPrint')?.addEventListener('click',()=>{document.body.classList.add('printing-payroll');window.print()});$('#closePayroll')?.addEventListener('click',()=>{try{const snap=savedSnapshot(s.id);if(!confirm('تقفيل محلي للموظف '+s.name+' بصافي '+currency(snap.calculation.total)+'؟ سيتم تثبيت الأرقام، بدون تسجيل صرف نقدي.'))return;closePayroll(s.id);render();toast('تم حفظ نسخة التقفيل المحلية')}catch(e){toast(e.message)}});$('#reopenPayroll')?.addEventListener('click',()=>safeSubmit('إعادة فتح التقفيل',field('سبب إعادة الفتح','reason'),f=>reopenPayroll(closedPayroll(s.id),f.get('reason'))))}
function employeeHoursSummary(){const employee=$('#branch').value;return card('إجمالي ساعات كل موظف — البريك مدفوع',`<div class="table-wrap"><table><tr><th>الموظف</th><th>الفرع الحالي</th><th>الورديات المغلقة</th><th>الساعات المدفوعة</th><th>منها رصيد افتتاحي</th><th>المفتوحة</th></tr>${allEmployees().filter(s=>(!reportFilter.employee||s.id===Number(reportFilter.employee))).map(s=>{const rows=reportRows().filter(p=>p.employeeId===s.id);const opening=(db.attendanceOpening||[]).filter(o=>Number(o.employeeId)===Number(s.id)&&(!reportFilter.from||o.date>=reportFilter.from)&&(!reportFilter.to||o.date<=reportFilter.to));if(!rows.length&&!opening.length&&reportFilter.branch&&s.branch!==reportFilter.branch)return '';const closed=rows.filter(p=>p.out),hours=closed.reduce((sum,p)=>sum+(Date.parse(p.out)-Date.parse(p.in))/36e5,0),openingHours=opening.reduce((x,o)=>x+Number(o.hours||0),0),openingShifts=opening.reduce((x,o)=>x+Number(o.shifts||0),0);return `<tr><td>${esc(s.name)}</td><td>${esc(s.branch)}</td><td>${closed.length}</td><td>${(hours+openingHours).toFixed(4)}</td><td>${opening.length?openingShifts+' شيفت / '+openingHours.toFixed(2)+' س':'—'}</td><td>${rows.length-closed.length}</td></tr>`}).join('')}</table></div><p class="score-explain">تقرير الحضور يجمع الورديات حسب يوم بداية الوردية. تقفيل المرتبات يقسم ساعات الوردية العابرة لحدود الفترة حتى لا تتكرر بين فترتين.</p>`)}
render=function(){payrollRender();if(role!=='الإدارة')return;if(page==='payroll'){$('#app').innerHTML=payrollView();bindPayroll()}if(page==='reports')$('#reportPaper').insertAdjacentHTML('beforeend',employeeHoursSummary())};
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-payroll'));
render();
